SEED = 62656385
BUDGET = 10000000
N = 12


def build():
    triples = []
    for a in range(N - 2):
        for b in range(a + 1, N - 1):
            for c in range(b + 1, N):
                triples.append((a, b, c))
    T = len(triples)
    tindex = {}
    for i in range(T):
        tindex[triples[i]] = i
    quads = []
    for a in range(N - 3):
        for b in range(a + 1, N - 2):
            for c in range(b + 1, N - 1):
                for d in range(c + 1, N):
                    quads.append((a, b, c, d))
    Q = len(quads)
    tq = []
    for t in range(T):
        tq.append([])
    for qi in range(Q):
        q = quads[qi]
        for k in range(4):
            rest = []
            for j in range(4):
                if j != k:
                    rest.append(q[j])
            tq[tindex[tuple(rest)]].append(qi)
    return triples, tindex, quads, T, Q, tq

TRIPLES, TINDEX, QUADS, T, Q, TQ = build()

ST = {
    'color': [-1] * T,
    'assigned': [0] * Q,
    'red': [0] * Q,
    'blue': [0] * Q,
    'nodes': 0,
    'seed': SEED,
    'budget': BUDGET,
}


def nxt():
    ST['seed'] = (ST['seed'] * 1103515245 + 12345) % 2147483648
    return ST['seed']


def try_assign(t, c):
    cnt = 0
    ST['color'][t] = c
    for qi in TQ[t]:
        ST['assigned'][qi] += 1
        if c == 0:
            ST['red'][qi] += 1
        else:
            ST['blue'][qi] += 1
        cnt += 1
        if ST['assigned'][qi] == 4 and (ST['red'][qi] == 4 or ST['blue'][qi] == 4):
            lst = TQ[t]
            for j in range(cnt):
                qj = lst[j]
                ST['assigned'][qj] -= 1
                if c == 0:
                    ST['red'][qj] -= 1
                else:
                    ST['blue'][qj] -= 1
            ST['color'][t] = -1
            return False
    return True


def undo(t):
    for qi in TQ[t]:
        ST['assigned'][qi] -= 1
        if ST['color'][t] == 0:
            ST['red'][qi] -= 1
        else:
            ST['blue'][qi] -= 1
    ST['color'][t] = -1


def dfs(t):
    ST['nodes'] += 1
    if ST['nodes'] > ST['budget']:
        raise RuntimeError('budget exhausted')
    if t == T:
        return True
    first = nxt() % 2
    if try_assign(t, first):
        if dfs(t + 1):
            return True
        undo(t)
    if try_assign(t, 1 - first):
        if dfs(t + 1):
            return True
        undo(t)
    return False


def verify(witness):
    # Fail closed: raise on any mismatch, absence, or failed check.
    if int(witness['N']) != N:
        raise ValueError('N mismatch')
    if int(witness['seed']) != SEED or int(witness['node_budget']) != BUDGET:
        raise ValueError('witness parameters mismatch verifier constants')
    if not dfs(0):
        raise RuntimeError('no colouring found within budget')
    # Independent exhaustive recheck over all 495 four-sets.
    for qi in range(Q):
        q = QUADS[qi]
        seen0 = False
        seen1 = False
        for k in range(4):
            rest = []
            for j in range(4):
                if j != k:
                    rest.append(q[j])
            c = ST['color'][TINDEX[tuple(rest)]]
            if c == 0:
                seen0 = True
            elif c == 1:
                seen1 = True
            else:
                raise ValueError('unassigned triple in recheck')
        if not (seen0 and seen1):
            raise ValueError('monochromatic 4-set found: %s' % (q,))
    return True
